ee:message.ee:set-payload:
%dw 2.0
output application/json
var calls = (vars.pendingTools default []) map ((t) -> {
    toolUseId: t.toolUseId,
    name: (t.name default ""),
    toolType: (t.'type' default "agent.tool_use"),
    key: (t.key default ""),
    "input": (t.'input' default {})
})
fun describe(t) = (t.name default "tool") ++ (if ((t.'input'.file_path?)) (" -> " ++ t.'input'.file_path) else "")
---
{
  id: vars.taskId,
  contextId: vars.contextId,
  kind: "task",
  status: {
    state: "input-required",
    message: {
      role: "agent",
      kind: "message",
      messageId: uuid(),
      parts: [
        { kind: "text", text: ("Approval required before the agent can run: " ++ ((calls map ((c) -> describe(c))) joinBy ", ") ++ ". Reply \"approve\" to allow, or \"deny\" to reject. (Programmatic clients may send a tool-confirmation-response DataPart for per-tool decisions.)") },
        { kind: "data", data: { "type": "tool-confirmation-request", taskId: vars.taskId, calls: calls } }
      ]
    }
  }
}

%dw 2.0
output application/json
fun baseName(fp) = ((fp default "") splitBy "/")[-1] default "artifact"
// Files written this turn PLUS any HITL-approved write gated last turn (its tool_use with content
// fired before the pause, so recover it from the persisted pending state for 'allow' decisions).
var approvedPending = ((if (vars.taskRec is Object) (vars.taskRec.pending default []) else []) filter ((t) -> (t.'input'.file_path?) and ((sizeOf((vars.confirmEvents default []) filter ((d) -> (d.tool_use_id == t.toolUseId) and ((d.result default '') == 'allow')))) > 0)) map ((t) -> { path: (t.'input'.file_path), content: (t.'input'.content default '') }))
var allFiles = ((vars.fileArtifacts default []) ++ approvedPending)
---
{
  id: vars.taskId,
  contextId: vars.contextId,
  kind: "task",
  status: { state: "completed" },
  artifacts: [
    {
      artifactId: "answer-" ++ vars.taskId,
      name: "Answer",
      parts: [ { kind: "text", text: (vars.finalText default "") } ]
    }
  ] ++ (allFiles groupBy ((f) -> f.path) pluck ((touches, path) -> {
    artifactId: baseName(path),
    name: baseName(path),
    parts: [ { kind: "text", text: (touches[-1].content default "") } ]
  }))
}

%dw 2.0
output application/json
---
{
  id: vars.taskId,
  contextId: vars.contextId,
  kind: "task",
  status: {
    state: "failed",
    message: { kind: "message", role: "agent", messageId: uuid(), parts: [ { kind: "text", text: ("Session error: " ++ (error.description default "unknown")) } ] }
  }
}
